"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[94240],{67005(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>c,default:()=>h,frontMatter:()=>u,metadata:()=>a,toc:()=>p});var i=t.cw((e,n)=>{const i=t.p+"assets/images/memoire-p10-1-8b9c233e1359d53cc58fccc4c4459aa2.png";t.d(n,["A",0,i])}),s=t.cw((e,n)=>{const i=t.p+"assets/images/memoire-p11-1-d25ebfc9c26f2ade6552b1c5af714573.png";t.d(n,["A",0,i])}),r=t.cw((e,n)=>{const i=t.p+"assets/images/memoire-p14-1-d394d4d49d919eeafe82c1686b3874c9.png";t.d(n,["A",0,i])});const a=JSON.parse('{"id":"scolarite/cpbx/s4/projet/activite-cerebrale","title":"Activit\xe9 c\xe9r\xe9brale, origine des signaux exploitables","description":"Origine et principe des interfaces cerveau-machine, P300 Matrix Speller, anatomie du syst\xe8me nerveux, \xe9lectroenc\xe9phalographie, marqueurs physiologiques et potentiel P300.","source":"@site/docs/scolarite/cpbx/s4/projet/activite-cerebrale.md","sourceDirName":"scolarite/cpbx/s4/projet","slug":"/scolarite/cpbx/s4/projet/activite-cerebrale","permalink":"/docs/scolarite/cpbx/s4/projet/activite-cerebrale","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1792955287000,"sidebarPosition":6,"frontMatter":{"title":"Activit\xe9 c\xe9r\xe9brale, origine des signaux exploitables","description":"Origine et principe des interfaces cerveau-machine, P300 Matrix Speller, anatomie du syst\xe8me nerveux, \xe9lectroenc\xe9phalographie, marqueurs physiologiques et potentiel P300.","sidebar_position":6},"sidebar":"tutorialSidebar","previous":{"title":"M\xe9moire : r\xe9sum\xe9 et introduction","permalink":"/docs/scolarite/cpbx/s4/projet/memoire"},"next":{"title":"Traitement du signal et apprentissage","permalink":"/docs/scolarite/cpbx/s4/projet/traitement-du-signal"}}');var l=t(74848),o=t(28453);const u={title:"Activit\xe9 c\xe9r\xe9brale, origine des signaux exploitables",description:"Origine et principe des interfaces cerveau-machine, P300 Matrix Speller, anatomie du syst\xe8me nerveux, \xe9lectroenc\xe9phalographie, marqueurs physiologiques et potentiel P300.",sidebar_position:6},c=void 0,d={},p=[{value:"Introduction aux ICM",id:"introduction-aux-icm",level:2},{value:"Origine des ICM, chronologie",id:"origine-des-icm-chronologie",level:3},{value:"G\xe9n\xe9ralit\xe9s",id:"g\xe9n\xe9ralit\xe9s",level:3},{value:"Un exemple d&#39;ICM : le &quot;P300 Matrix Speller&quot;",id:"un-exemple-dicm--le-p300-matrix-speller",level:3},{value:"Anatomie et physiologie",id:"anatomie-et-physiologie",level:2},{value:"Description g\xe9n\xe9rale du syst\xe8me nerveux",id:"description-g\xe9n\xe9rale-du-syst\xe8me-nerveux",level:3},{value:"\xc9lectrophysiologie : \xe9lectroenc\xe9phalographie",id:"\xe9lectrophysiologie--\xe9lectroenc\xe9phalographie",level:3},{value:"Marqueurs physiologiques pour le contr\xf4le d&#39;ICM r\xe9actives",id:"marqueurs-physiologiques-pour-le-contr\xf4le-dicm-r\xe9actives",level:3},{value:"Exploitation d&#39;un signal particulier : le P300",id:"exploitation-dun-signal-particulier--le-p300",level:2},{value:"\xc9v\xe9nements d\xe9clencheurs",id:"\xe9v\xe9nements-d\xe9clencheurs",level:3},{value:"Construction de la r\xe9ponse, acteurs sollicit\xe9s",id:"construction-de-la-r\xe9ponse-acteurs-sollicit\xe9s",level:3},{value:"Construction d&#39;ICM bas\xe9es sur le P300 : exemple du P300 Matrix Speller",id:"construction-dicm-bas\xe9es-sur-le-p300--exemple-du-p300-matrix-speller",level:3},{value:"Conclusion",id:"conclusion",level:2}];function m(e){const n={a:"a",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",section:"section",sup:"sup",ul:"ul",...(0,o.R)(),...e.components};return(0,l.jsxs)(l.Fragment,{children:[(0,l.jsx)(n.p,{children:"Premier chapitre du m\xe9moire : l'activit\xe9 c\xe9r\xe9brale \xe0 l'origine de signaux exploitables par les machines."}),"\n",(0,l.jsx)(n.h2,{id:"introduction-aux-icm",children:"Introduction aux ICM"}),"\n",(0,l.jsx)(n.h3,{id:"origine-des-icm-chronologie",children:"Origine des ICM, chronologie"}),"\n",(0,l.jsxs)(n.p,{children:["Les interfaces cerveau-machine (ICM) ne sont pas un concept r\xe9cent. D\xe8s les pr\xe9mices de l'informatique, en 1945, les sc\xe9naristes et auteurs de science-fiction imaginent des machines capables de communiquer avec le cerveau humain. Parmi eux, Isaac Asimov s'illustre par l'invention d'un grand nombre d'objets fictifs agissant sur le cerveau, dont le \"c\xe9r\xe9broanalyseur\" (",(0,l.jsx)(n.em,{children:"Les cavernes d'acier"}),", 1956), machine permettant l'interpr\xe9tation des champs \xe9lectromagn\xe9tiques g\xe9n\xe9r\xe9s par les neurones."]}),"\n",(0,l.jsx)(n.p,{children:"La cr\xe9ativit\xe9 des auteurs est nourrie par les avanc\xe9es en neurosciences. La premi\xe8re observation des signaux \xe9lectriques g\xe9n\xe9r\xe9s par le cerveau, en 1875, ouvre la voie \xe0 de nombreuses perspectives d'\xe9tudes. Il faudra cependant attendre les d\xe9couvertes majeures du 20\xe8me si\xe8cle en chimie, biologie et physique pour mettre au point des outils et m\xe9thodes permettant d'\xe9tudier le fonctionnement du cerveau. Le d\xe9veloppement de l'\xe9lectroenc\xe9phalographie entre 1950 et 1960 permet la cr\xe9ation des premi\xe8res interfaces d\xe8s 1970 ; la fiction a finalement rejoint la r\xe9alit\xe9."}),"\n",(0,l.jsx)(n.p,{children:"Parmi les premiers mod\xe8les d'ICM, on peut citer l'interface intracorticale mise au point par Philip Kennedy ou encore le mod\xe8le de Fetz, utilisant l'activit\xe9 c\xe9r\xe9brale de singes (1970). En 1999, Yang Dang et son \xe9quipe parviennent \xe0 cr\xe9er un syst\xe8me capable de reconstruire la perception visuelle d'un chat. Cette derni\xe8re exp\xe9rience ouvre la voie au d\xe9veloppement de nombreuses ICM permettant le contr\xf4le par l'activit\xe9 c\xe9r\xe9brale de bras m\xe9caniques, de curseurs d'ordinateurs ou encore de claviers virtuels."}),"\n",(0,l.jsx)(n.h3,{id:"g\xe9n\xe9ralit\xe9s",children:"G\xe9n\xe9ralit\xe9s"}),"\n",(0,l.jsx)(n.p,{children:"On peut d\xe9finir simplement une ICM comme une interface de communication directe entre le cerveau et un dispositif externe (g\xe9n\xe9ralement un ordinateur). Pour que deux \xe9l\xe9ments (ici la machine et le cerveau) puissent entrer en communication, il est n\xe9cessaire qu'ils parlent le m\xeame langage. D'o\xf9 l'int\xe9r\xeat d'exploiter les signaux \xe9lectriques g\xe9n\xe9r\xe9s par le cerveau, car ceux-ci refl\xe8tent l'\xe9tat mental de l'utilisateur. Ils peuvent donc \xeatre interpr\xe9t\xe9s, compris par la machine."}),"\n",(0,l.jsx)(n.p,{children:"Parmi les ICM, certaines sont invasives, c'est-\xe0-dire qu'elles utilisent des \xe9lectrodes implant\xe9es en profondeur dans le cerveau, afin de capter l'influx nerveux. Mais les ICM peuvent \xe9galement \xeatre non invasives. En effet, la pose d'\xe9lectrodes en surface du cuir chevelu permet de d\xe9tecter des r\xe9sidus de l'activit\xe9 c\xe9r\xe9brale, et ce sans intervention chirurgicale. L'inconv\xe9nient de ces m\xe9thodes non invasives est que les signaux consid\xe9r\xe9s sont tr\xe8s faibles. Cependant, elles restent le meilleur compromis entre les risques de l'exp\xe9rience (infection, atteinte \xe0 l'int\xe9grit\xe9 du cerveau) et la qualit\xe9 du signal. Dans le cadre de ce projet, nous \xe9tudierons donc exclusivement des ICM non invasives."}),"\n",(0,l.jsx)(n.p,{children:"On utilise g\xe9n\xe9ralement les ICM afin de pallier une inaptitude, dans l'objectif d'augmenter les capacit\xe9s de l'utilisateur \xe0 effectuer une action en court-circuitant l'encha\xeenement conventionnel \"cerveau-nerfs-muscles-action\". Ainsi, les ICM trouvent des applications concr\xe8tes dans le domaine m\xe9dical. Elles peuvent \xeatre utilis\xe9es afin de restaurer des facult\xe9s (ou\xefe, vue) ou encore servir le domaine clinique (mise au point de fauteuils roulants contr\xf4l\xe9s par l'activit\xe9 c\xe9r\xe9brale par exemple)."}),"\n",(0,l.jsx)(n.h3,{id:"un-exemple-dicm--le-p300-matrix-speller",children:'Un exemple d\'ICM : le "P300 Matrix Speller"'}),"\n",(0,l.jsx)(n.p,{children:"Le P300 Matrix Speller est une interface tr\xe8s r\xe9pandue. Introduit en 1988 par les chercheurs Farwell et Donchin, ce dispositif s'est impos\xe9 comme un cas d'\xe9cole d'ICM. Il s'agit d'une interface permettant la communication \xe9crite. Une analogie (un peu simpliste) avec une \"machine \xe0 \xe9crire mentale\" semble pertinente, car le P300 Matrix Speller se sert uniquement de l'activit\xe9 c\xe9r\xe9brale de son utilisateur pour d\xe9tecter la lettre qu'il souhaite \xe9crire et l'inscrire \xe0 l'\xe9cran. Ainsi, l'utilisateur peut \xe9crire des mots sur un \xe9cran, en se servant exclusivement de son activit\xe9 c\xe9r\xe9brale."}),"\n",(0,l.jsx)(n.p,{children:"Plus pr\xe9cis\xe9ment, le P300 Matrix Speller se base sur la d\xe9tection d'une singularit\xe9 dans l'activit\xe9 c\xe9r\xe9brale. Cette singularit\xe9 prend la forme d'une onde d'amplitude caract\xe9ristique appel\xe9e potentiel P300. Son apparition est interpr\xe9t\xe9e comme la cons\xe9quence d'\xe9tats mentaux particuliers. Dans le cas du P300 Matrix Speller, on montre que l'onde P300 survient lorsque le caract\xe8re cible, c'est-\xe0-dire la lettre ou le chiffre que l'on veut inscrire, est pr\xe9sent\xe9 \xe0 l'utilisateur."}),"\n",(0,l.jsx)(n.p,{children:"Afin d'optimiser l'apparition de la P300 lors de l'utilisation du syst\xe8me, un paradigme de stimulation a \xe9t\xe9 mis au point. Ce paradigme (Paradigme Ligne/Colonne) se pr\xe9sente sous la forme d'une matrice, affich\xe9e sur un \xe9cran et dans laquelle sont r\xe9pertori\xe9s les diff\xe9rents caract\xe8res (lettres et chiffres) n\xe9cessaires \xe0 l'\xe9criture. Lorsque le P300 Speller fonctionne, les lignes et les colonnes de la matrice s'illuminent successivement, dans un clignotement tr\xe8s rapide. L'utilisateur est suppos\xe9 fixer et focaliser son attention sur le caract\xe8re souhait\xe9. L'illumination du caract\xe8re cible initie la r\xe9ponse P300."}),"\n",(0,l.jsx)(n.p,{children:(0,l.jsx)(n.img,{alt:"Figure 1.1 : sch\xe9ma de principe du P300 Matrix Speller",src:i().A+"",width:"533",height:"228"})}),"\n",(0,l.jsx)(n.p,{children:(0,l.jsxs)(n.em,{children:["Figure 1.1 : sch\xe9ma de principe du P300 Matrix Speller. Si le lecteur souhaite avoir une repr\xe9sentation visuelle du processus d'illumination des lignes et des colonnes, nous le redirigeons vers ",(0,l.jsx)(n.a,{href:"https://www.youtube.com/watch?v=xvfxsNpaRGI",children:"cette vid\xe9o"}),"."]})}),"\n",(0,l.jsx)(n.p,{children:"D'autres paradigmes de stimulation existent. Cependant, nous traiterons exclusivement du Paradigme Ligne/Colonne."}),"\n",(0,l.jsx)(n.p,{children:"Le P300 Speller est constitu\xe9 de plusieurs \xe9l\xe9ments. D'abord un casque EEG (\xe9lectroenc\xe9phalogramme) permettant de d\xe9tecter l'activit\xe9 \xe9lectrique en surface du cuir chevelu par l'interm\xe9diaire d'\xe9lectrodes. Ensuite, un bo\xeetier permettant la r\xe9ception et le traitement des signaux capt\xe9s par les \xe9lectrodes. Enfin, un \xe9cran d'ordinateur qui assure la stimulation de l'utilisateur et lui permet de visualiser le mot en cours d'\xe9criture (figure 1.1)."}),"\n",(0,l.jsx)(n.h2,{id:"anatomie-et-physiologie",children:"Anatomie et physiologie"}),"\n",(0,l.jsxs)(n.p,{children:["Afin de comprendre le fonctionnement des ICM non invasives, il est essentiel de d\xe9terminer l'origine des signaux exploitables et d'expliciter leur lien avec l'activit\xe9 c\xe9r\xe9brale et l'\xe9tat mental de l'utilisateur. Cette section propose au lecteur une introduction au syst\xe8me nerveux et \xe0 ses m\xe9canismes ainsi qu'une description d\xe9taill\xe9e des techniques d'\xe9lectroenc\xe9phalographie et de la notion de marqueur physiologique",(0,l.jsx)(n.sup,{children:(0,l.jsx)(n.a,{href:"#user-content-fn-clerc",id:"user-content-fnref-clerc","data-footnote-ref":!0,"aria-describedby":"footnote-label",children:"1"})}),"."]}),"\n",(0,l.jsx)(n.h3,{id:"description-g\xe9n\xe9rale-du-syst\xe8me-nerveux",children:"Description g\xe9n\xe9rale du syst\xe8me nerveux"}),"\n",(0,l.jsx)(n.p,{children:"Le neurone est \xe0 la base du syst\xe8me nerveux. Il s'agit d'une cellule dont le r\xf4le est de transmettre des informations, v\xe9hicul\xe9es sous forme de signaux \xe9lectriques appel\xe9s potentiels d'action. Par l'interm\xe9diaire de prolongements appel\xe9s axones et dendrites, les neurones sont capables d'interagir, via la propagation de potentiels d'action cr\xe9\xe9s par d\xe9polarisation de la membrane axonale. Cette interaction a lieu au niveau des synapses, zone s\xe9parant l'axone d'un neurone de la dendrite d'un autre neurone."}),"\n",(0,l.jsx)(n.p,{children:"Les neurones s'organisent en voies, faisceaux ou r\xe9seaux. La mani\xe8re dont ils sont connect\xe9s entre eux d\xe9termine le r\xf4le de ces structures. On distingue classiquement le syst\xe8me nerveux central (SNC) et le syst\xe8me nerveux p\xe9riph\xe9rique (SNP). Nous nous focaliserons sur le SNC et plus particuli\xe8rement sur l'enc\xe9phale."}),"\n",(0,l.jsx)(n.p,{children:"L'enc\xe9phale est constitu\xe9 du tronc c\xe9r\xe9bral, du cervelet et de deux h\xe9misph\xe8res. Les h\xe9misph\xe8res comportent plusieurs lobes externes (frontal, pari\xe9tal, temporal et occipital)."}),"\n",(0,l.jsx)(n.p,{children:"Le lobe frontal intervient essentiellement dans la planification, le langage et le mouvement volontaire ; il est compos\xe9 du gyrus pr\xe9central, des aires pr\xe9motrices et des aires pr\xe9frontales. Le lobe pari\xe9tal joue un r\xf4le important dans l'int\xe9gration des informations issues des diff\xe9rentes modalit\xe9s sensorielles. Cette r\xe9gion est impliqu\xe9e dans la perception de l'espace et dans l'attention. Le lobe temporal est impliqu\xe9 dans l'audition, le langage, la m\xe9moire et la vision des formes complexes. Le lobe occipital est le centre visuel ; il permet la reconnaissance des orientations et des contours des images."}),"\n",(0,l.jsx)(n.p,{children:(0,l.jsx)(n.img,{alt:"Figure 1.2 : les diff\xe9rents lobes constituant le cerveau humain",src:s().A+"",width:"344",height:"314"})}),"\n",(0,l.jsx)(n.p,{children:"Le cortex se situe \xe0 la surface des h\xe9misph\xe8res (figure 1.2). Les aires primaires du cortex regroupent le cortex moteur primaire et les aires qui r\xe9ceptionnent les stimuli sensoriels. Elles se distinguent des aires secondaires, qui correspondent \xe0 des traitements \xe9labor\xe9s des informations. On peut \xe9galement \xe9voquer les aires associatives, \xe0 l'origine des fonctions cognitives, qui r\xe9gulent l'attention port\xe9e \xe0 la d\xe9tection et \xe0 l'identification des stimuli. Enfin, le cervelet constitue \xe9galement un \xe9l\xe9ment fondamental du SNC. Il est le centre majeur de la coordination, de l'\xe9quilibre et du contr\xf4le du tonus musculaire. Il permet la r\xe9alisation de t\xe2ches motrices complexes."}),"\n",(0,l.jsx)(n.h3,{id:"\xe9lectrophysiologie--\xe9lectroenc\xe9phalographie",children:"\xc9lectrophysiologie : \xe9lectroenc\xe9phalographie"}),"\n",(0,l.jsx)(n.p,{children:"Nous avons vu pr\xe9c\xe9demment que l'unit\xe9 fonctionnelle du syst\xe8me nerveux est le neurone, et que cette cellule communique par l'interm\xe9diaire de signaux \xe9lectrochimiques. L'activit\xe9 c\xe9r\xe9brale exploit\xe9e pour cr\xe9er des interfaces cerveau-machine est donc de nature \xe9lectrique. Il s'agit maintenant d'\xeatre capable de r\xe9cup\xe9rer cette activit\xe9 \xe9lectrique et de lui donner un sens, c'est-\xe0-dire de la relier \xe0 des processus cognitifs."}),"\n",(0,l.jsx)(n.p,{children:"Les signaux g\xe9n\xe9r\xe9s en profondeur dans la bo\xeete cr\xe2nienne (ordre de 1000 mV) peuvent \xeatre d\xe9tect\xe9s \xe0 la surface du cuir chevelu via une m\xe9thode d'acquisition de l'activit\xe9 c\xe9r\xe9brale appel\xe9e \xe9lectroenc\xe9phalographie (abr\xe9g\xe9e EEG)."}),"\n",(0,l.jsx)(n.p,{children:"Lorsqu'un neurone re\xe7oit un potentiel post-synaptique, c'est-\xe0-dire un signal unitaire produit en aval d'une synapse, un mouvement d'ions est initi\xe9 \xe0 travers la membrane cellulaire, r\xe9sultant en un courant \xe9lectrique qui se propage dans le volume de la t\xeate. Cette propagation est ind\xe9pendante de l'activit\xe9 \xe9lectrique qui participe au fonctionnement du cerveau. Le courant g\xe9n\xe9r\xe9 par un seul neurone est ind\xe9tectable \xe0 la surface du cuir chevelu. Pour obtenir des signaux d'amplitude suffisante pour \xeatre mesur\xe9e, il faut qu'un grand nombre de neurones soient actifs en m\xeame temps."}),"\n",(0,l.jsx)(n.p,{children:"Les champs produits par les neurones sont optimaux lorsque les dendrites sont parall\xe8les entre elles et que les neurones \xe0 l'origine des signaux sont de forme pyramidale (on parle alors de neurones pyramidaux). Une grande partie de l'activit\xe9 c\xe9r\xe9brale enregistr\xe9e en EEG provient de champs \xe9lectriques g\xe9n\xe9r\xe9s avec cette configuration."}),"\n",(0,l.jsx)(n.p,{children:"D'un point de vue pratique, l'EEG mesure une diff\xe9rence de potentiels \xe9lectriques entre des \xe9lectrodes r\xe9parties sur l'ensemble du cuir chevelu et une \xe9lectrode de r\xe9f\xe9rence pour d\xe9terminer le champ \xe9lectrique associ\xe9. Les informations en provenance de chaque \xe9lectrode sont d'abord analys\xe9es s\xe9par\xe9ment, avant d'\xeatre recoup\xe9es pour une analyse plus globale."}),"\n",(0,l.jsx)(n.p,{children:'Lors de la r\xe9alisation d\'une t\xe2che cognitive, il est n\xe9cessaire de multiplier les stimulations car les r\xe9ponses unitaires sont faibles. De plus, il faut arriver \xe0 extraire les signaux d\'int\xe9r\xeat du "bruit" environnant, cons\xe9cutif \xe0 l\'activit\xe9 "normale" du cerveau en \xe9veil.'}),"\n",(0,l.jsxs)(n.p,{children:["Une \xe9tape pr\xe9c\xe9dant l'analyse \xe0 proprement parler des signaux (voir le chapitre ",(0,l.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/traitement-du-signal",children:"Traitement du signal et apprentissage"}),") consiste en la localisation des sources. Il s'agit d'estimer o\xf9 la r\xe9ponse cognitive a \xe9t\xe9 construite dans le cortex avant sa d\xe9tection \xe0 la surface du cuir chevelu. Cette \xe9tape n'est pas toujours \xe9vidente car l'EEG ne capte en surface que des r\xe9sidus d'activit\xe9 c\xe9r\xe9brale : au cours de leur propagation dans la bo\xeete cr\xe2nienne, les signaux se sont att\xe9nu\xe9s et une partie de l'information est perdue."]}),"\n",(0,l.jsx)(n.p,{children:"L'estimation des sources se base sur le calcul des champs \xe9lectriques produits par les neurones, consid\xe9r\xe9s comme des dip\xf4les. Ce calcul n\xe9cessite de mod\xe9liser la bo\xeete cr\xe2nienne et de prendre en compte la conductivit\xe9 des tissus. L'approche lin\xe9aire est souvent privil\xe9gi\xe9e ; elle consiste en la superposition de l'activit\xe9 d'un grand nombre de sources dipolaires, distribu\xe9es uniform\xe9ment."}),"\n",(0,l.jsx)(n.p,{children:"Ainsi, l'EEG permet de d\xe9tecter des signaux \xe0 la surface du cuir chevelu et de localiser les sources de ces signaux en profondeur dans la bo\xeete cr\xe2nienne. Le principal avantage de l'EEG est son excellente r\xe9solution temporelle. D'autres techniques de mesure, comme l'Imagerie par R\xe9sonance Magn\xe9tique fonctionnelle (IRMf), permettent \xe9galement d'appr\xe9hender l'activit\xe9 c\xe9r\xe9brale, avec leurs avantages et inconv\xe9nients respectifs. Dans le cas de l'IRMf, la r\xe9solution temporelle est mauvaise et le dispositif est encombrant. Cependant, cette technique offre une tr\xe8s bonne r\xe9solution spatiale. Le choix de la technique \xe0 utiliser d\xe9pend donc des caract\xe9ristiques du ph\xe9nom\xe8ne que l'on veut observer."}),"\n",(0,l.jsx)(n.h3,{id:"marqueurs-physiologiques-pour-le-contr\xf4le-dicm-r\xe9actives",children:"Marqueurs physiologiques pour le contr\xf4le d'ICM r\xe9actives"}),"\n",(0,l.jsx)(n.p,{children:"Les interfaces cerveau-machine exploitent les signaux r\xe9cup\xe9r\xe9s par EEG en cherchant \xe0 \xe9tablir des corr\xe9lations entre les caract\xe9ristiques des signaux et la t\xe2che mentale en cours."}),"\n",(0,l.jsx)(n.p,{children:"Pour ce faire, le syst\xe8me recherche des formes de signaux particuli\xe8res, se distinguant du bruit de fond par leur amplitude, leur fr\xe9quence ou leur temps de latence. Ces signaux d'int\xe9r\xeat sont appel\xe9s \"marqueurs physiologiques\". Nous nous focaliserons ici sur les marqueurs physiologiques des ICM r\xe9actives, c'est-\xe0-dire des interfaces proposant une stimulation \xe0 l'utilisateur afin de produire une modification de son \xe9tat mental. Pour pouvoir \xeatre utilis\xe9s en tant que tels, les marqueurs physiologiques doivent \xeatre localisables dans l'espace et/ou le temps. Ils ne sont pas propres \xe0 une t\xe2che mentale en particulier mais plut\xf4t \xe0 un type de r\xe9ponse cognitive. Ainsi, un m\xeame marqueur physiologique peut \xeatre utilis\xe9 par plusieurs ICM."}),"\n",(0,l.jsx)(n.p,{children:"La d\xe9tection d'un marqueur physiologique refl\xe8te l'apparition d'un \xe9v\xe9nement remarquable dans l'activit\xe9 c\xe9r\xe9brale, par exemple une variation importante de l'activit\xe9 \xe9lectrique due \xe0 une succession particuli\xe8re d'activations et de d\xe9sactivations dans une assembl\xe9e de neurones. L'enjeu est alors de caract\xe9riser la stimulation ou l'\xe9tat mental \xe0 l'origine de cette variation."}),"\n",(0,l.jsx)(n.p,{children:"Lorsque l'on dispose d'une bonne r\xe9solution spatiale, il est possible de localiser avec pr\xe9cision la r\xe9gion c\xe9r\xe9brale concern\xe9e par le changement dans l'activit\xe9 nerveuse, et donc de relier l'apparition du marqueur avec les fonctionnalit\xe9s connues de cette r\xe9gion. Lorsque l'on dispose d'une bonne r\xe9solution temporelle, on peut directement associer l'apparition du marqueur \xe0 l'\xe9tat mental de l'utilisateur, et en d\xe9duire la signification du marqueur."}),"\n",(0,l.jsx)(n.p,{children:"En EEG, les marqueurs physiologiques sont commun\xe9ment appel\xe9s potentiels \xe9voqu\xe9s (abr\xe9g\xe9 PE). Il s'agit de modifications du potentiel \xe9lectrique g\xe9n\xe9r\xe9 par le syst\xe8me nerveux en r\xe9ponse \xe0 une stimulation externe (pr\xe9sentation d'une image, d'un son...) ou interne (modification de l'attention, pr\xe9paration motrice...). Lorsqu'un PE ne peut \xeatre g\xe9n\xe9r\xe9 que par l'interm\xe9diaire d'une stimulation externe, on le dit exog\xe8ne. Par opposition, un PE pouvant \xe9ventuellement \xeatre g\xe9n\xe9r\xe9 par stimulation interne est dit endog\xe8ne."}),"\n",(0,l.jsx)(n.p,{children:"En conclusion, il est important de comprendre que l'ICM ne prend pas en compte l'int\xe9gralit\xe9 de l'activit\xe9 c\xe9r\xe9brale de mani\xe8re continue. Elle se focalise plut\xf4t sur des informations remarquables, obtenues sous forme de signaux particuliers : les marqueurs physiologiques (appel\xe9s parfois PE). Ces marqueurs doivent \xeatre reli\xe9s spatialement ou temporellement \xe0 des \xe9v\xe9nements (\xe9tat mental particulier, stimulus) afin que leur apparition prenne un sens et qu'ils puissent \xeatre utilis\xe9s par l'interface."}),"\n",(0,l.jsx)(n.h2,{id:"exploitation-dun-signal-particulier--le-p300",children:"Exploitation d'un signal particulier : le P300"}),"\n",(0,l.jsx)(n.p,{children:"La d\xe9tection des marqueurs physiologiques constitue le premier maillon de la cha\xeene de communication qu'\xe9tablit une interface cerveau-machine. Un marqueur particulier est \xe0 la base de l'interface utilis\xe9e dans le cadre de notre projet. Il s'agit du potentiel P300."}),"\n",(0,l.jsx)(n.p,{children:"Le potentiel P300 est pour la premi\xe8re fois observ\xe9 en 1964 par les chercheurs Chapman et Bragdon. En 1965, Sutton en propose une caract\xe9risation : il s'agit d'une onde d'amplitude positive sujette \xe0 une importante d\xe9formation, atteignant un pic au bout de 300 ms apr\xe8s le stimulus. Cette d\xe9finition du P300 justifie son nom. La lettre \"P\" indique que l'onde pr\xe9sente une amplitude positive, \"300\" donne son temps de latence (en ms). Il s'agit d'un PE endog\xe8ne ; l'onde peut donc \xeatre g\xe9n\xe9r\xe9e en l'absence de stimulation."}),"\n",(0,l.jsx)(n.p,{children:"Depuis les ann\xe9es 1970, la P300 est utilis\xe9e pour la compr\xe9hension de divers processus cognitifs ainsi que pour la d\xe9tection de certains troubles mentaux. Les signaux d\xe9tect\xe9s sur le cuir chevelu d'individus malades pr\xe9sentent une modification d'amplitude et de temps de latence. Cette particularit\xe9 peut donc servir d'outil de pr\xe9vention ou de r\xe9f\xe9rence. Cependant, malgr\xe9 les centaines d'\xe9tudes men\xe9es depuis sa d\xe9couverte, l'utilit\xe9 de la P300 en m\xe9decine reste limit\xe9e, car il est difficile de d\xe9finir avec pr\xe9cision les r\xf4les des diff\xe9rentes structures suppos\xe9es responsables de son apparition."}),"\n",(0,l.jsx)(n.p,{children:"Nous allons donc nous efforcer de d\xe9crire, de mani\xe8re concise et cr\xe9dible, les possibles acteurs et stimulations \xe0 l'origine de la r\xe9ponse P300. Nous garderons cependant un certain recul par rapport \xe0 ces informations, qui sont de l'ordre de l'hypoth\xe8se."}),"\n",(0,l.jsx)(n.h3,{id:"\xe9v\xe9nements-d\xe9clencheurs",children:"\xc9v\xe9nements d\xe9clencheurs"}),"\n",(0,l.jsx)(n.p,{children:"L'observation de r\xe9ponses comportant l'onde P300 \xe0 la suite de diff\xe9rents types de stimulations permet d'en distinguer deux sous-composantes, respectivement appel\xe9es P3a et P3b."}),"\n",(0,l.jsxs)(n.p,{children:["La P3a (appel\xe9e en anglais ",(0,l.jsx)(n.em,{children:"novelty P3"}),") est associ\xe9e \xe0 un engagement important de l'attention lors de changements brusques dans l'environnement exp\xe9rimental ainsi qu'\xe0 la r\xe9action du sujet face \xe0 la nouveaut\xe9. C'est donc une r\xe9ponse \xe0 un effet de surprise qui est attendue."]}),"\n",(0,l.jsx)(n.p,{children:"Dans le cas particulier o\xf9 le sujet r\xe9alise une \"t\xe2che de discrimination\", c'est-\xe0-dire qu'il se concentre sur un \xe9v\xe9nement \"cible\" diss\xe9min\xe9 parmi des \xe9v\xe9nements non attendus et plus fr\xe9quents, l'onde P3a est suivie par l'onde P3b."}),"\n",(0,l.jsx)(n.p,{children:"Plus l'\xe9v\xe9nement cible est rare, plus la r\xe9ponse P3b sera importante. Cette composante est en lien avec la m\xe9moire et la prise de d\xe9cision."}),"\n",(0,l.jsxs)(n.p,{children:["Bien qu'hypoth\xe9tique, cette s\xe9paration de la P300 en deux sous-composantes s'est av\xe9r\xe9e judicieuse d'un point de vue pratique, en m\xe9decine notamment. De plus, elle permet de faire la distinction entre deux groupes d'acteurs (aires c\xe9r\xe9brales, neurotransmetteurs) participant \xe0 l'un ou l'autre des aspects du signal. D'autres d\xe9coupes encore plus pr\xe9cises de l'onde P300 ont \xe9t\xe9 propos\xe9es avec, en plus des composantes P3a et P3b, l'ajout d'une onde lente (",(0,l.jsx)(n.em,{children:"Slow Wave"}),") et d'ondes apparaissant sp\xe9cifiquement lorsque l'individu doit faire un choix simple (",(0,l.jsx)(n.em,{children:"Simple Reaction"}),") ou complexe (",(0,l.jsx)(n.em,{children:"Choice Reaction"}),")."]}),"\n",(0,l.jsx)(n.p,{children:"Nous laisserons de c\xf4t\xe9 ces composantes mineures pour nous concentrer principalement sur la P3a et la P3b. Il est cependant \xe0 retenir que l'onde P300 est constitu\xe9e de plusieurs sous-composantes qui t\xe9moignent, en surface du cuir chevelu, d'\xe9tapes distinctes du traitement interne de l'information par le cerveau."}),"\n",(0,l.jsx)(n.h3,{id:"construction-de-la-r\xe9ponse-acteurs-sollicit\xe9s",children:"Construction de la r\xe9ponse, acteurs sollicit\xe9s"}),"\n",(0,l.jsx)(n.p,{children:"Selon une approche purement \xe9lectrophysiologique, le potentiel P300 est initi\xe9 par les potentiels postsynaptiques g\xe9n\xe9r\xe9s par les neurones pyramidaux. Toutefois, il est largement admis que les acteurs \xe0 l'origine de la P300 sont multiples. Les donn\xe9es actuelles permettent les affirmations suivantes :"}),"\n",(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"La composante P3a d\xe9pend principalement de l'int\xe9grit\xe9 du lobe frontal et de la production du neurotransmetteur dopamine."}),"\n",(0,l.jsx)(n.li,{children:"La composante P3b d\xe9pend principalement de l'int\xe9grit\xe9 du carrefour temporo-pari\xe9tal et de la production de noradr\xe9naline."}),"\n"]}),"\n",(0,l.jsx)(n.p,{children:"D'autres acteurs anatomiques, m\xeame s'ils ne contribuent pas directement \xe0 la g\xe9n\xe9ration du signal, sont \xe0 prendre en compte, comme la formation hippocampique."}),"\n",(0,l.jsx)(n.p,{children:"Le signal, apr\xe8s g\xe9n\xe9ration, progresse \xe0 travers les neurones pyramidaux. Le champ induit se propage dans la bo\xeete cr\xe2nienne jusqu'en surface du cuir chevelu, o\xf9 l'on peut le d\xe9tecter."}),"\n",(0,l.jsx)(n.h3,{id:"construction-dicm-bas\xe9es-sur-le-p300--exemple-du-p300-matrix-speller",children:"Construction d'ICM bas\xe9es sur le P300 : exemple du P300 Matrix Speller"}),"\n",(0,l.jsx)(n.p,{children:"L'onde P300 se singularise par son amplitude et son temps de latence. On peut donc l'utiliser en tant que marqueur physiologique pour fabriquer des ICM. Le P300 Matrix Speller est un exemple type d'interface bas\xe9e sur la d\xe9tection de la P300."}),"\n",(0,l.jsx)(n.p,{children:"Afin de d\xe9clencher l'apparition de la P300, le speller doit stimuler l'activit\xe9 c\xe9r\xe9brale de l'utilisateur. Comme expliqu\xe9 plus haut (P300 Matrix Speller), la stimulation est effectu\xe9e par l'interm\xe9diaire du Paradigme Ligne/Colonne : lorsque la lettre cible s'\xe9claire, une r\xe9ponse P300 est suppos\xe9e se produire chez l'utilisateur. Plus pr\xe9cis\xe9ment, on s'attend \xe0 observer la composante P3b de la P300, car il s'agit ici d'une t\xe2che de discrimination (voir \xc9v\xe9nements d\xe9clencheurs)."}),"\n",(0,l.jsx)(n.p,{children:'D\'autres exemples de paradigmes existent, comportant leurs propres sp\xe9cificit\xe9s, avantages et limites. On peut citer le "Single character paradigm", dans lequel les caract\xe8res s\'illuminent ponctuellement les uns apr\xe8s les autres, ou encore le "checkerboard paradigm", qui est un damier en noir et blanc sur lequel sont inscrites les lettres de l\'alphabet.'}),"\n",(0,l.jsx)(n.p,{children:"L'ICM fait ensuite le lien entre l'apparition de la P300 et la lettre cible. Nous verrons ult\xe9rieurement que ce lien n'est pas \xe9vident et n\xe9cessite en amont un gros travail de traitement des signaux."}),"\n",(0,l.jsx)(n.p,{children:"La d\xe9tection de l'activit\xe9 c\xe9r\xe9brale en surface du cuir chevelu, dans l'exemple du P300 Speller, peut \xeatre effectu\xe9e par l'interm\xe9diaire de 32 \xe9lectrodes actives. Cela comprend une \xe9lectrode servant de r\xe9f\xe9rence et une \xe9lectrode permettant de mesurer l'activit\xe9 c\xe9r\xe9brale de fond, appel\xe9e \"ground\". Le contact entre les \xe9lectrodes et le cuir chevelu est g\xe9n\xe9ralement assur\xe9 par un gel. La disposition des \xe9lectrodes n'est pas laiss\xe9e au hasard car, selon l'endroit o\xf9 elles sont pos\xe9es (figure 1.3), les informations transmises n'ont pas le m\xeame sens et l'importance accord\xe9e \xe0 chaque \xe9lectrode diff\xe8re."}),"\n",(0,l.jsx)(n.p,{children:(0,l.jsx)(n.img,{alt:"Figure 1.3 : placement des diff\xe9rentes \xe9lectrodes pour un casque EEG, hors \xe9lectrode de r\xe9f\xe9rence et ground",src:r().A+"",width:"355",height:"264"})}),"\n",(0,l.jsx)(n.p,{children:"Une d\xe9tection efficace de l'activit\xe9 c\xe9r\xe9brale permet d'\xe9tablir un \xe9lectroenc\xe9phalogramme fiable, dont l'exploitation permet de faire la distinction entre l'onde P300 et les autres signaux. Cette \xe9tape n'est donc pas \xe0 n\xe9gliger, l'\xe9lectroenc\xe9phalogramme constituant la base de donn\xe9es du syst\xe8me."}),"\n",(0,l.jsxs)(n.p,{children:["Cependant, m\xeame en soignant l'aspect mat\xe9riel du dispositif (qualit\xe9 et disposition des \xe9lectrodes, qualit\xe9 de la stimulation), l'obtention d'un \xe9lectroenc\xe9phalogramme fiable n'est pas garantie, car de nombreux facteurs peuvent perturber la r\xe9ponse P300. Ces facteurs (physiologiques ou li\xe9s aux caract\xe9ristiques du stimulus) seront d\xe9taill\xe9s dans le chapitre ",(0,l.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/implementation-p300-speller",children:"Exp\xe9rimentation : impl\xe9mentation du P300 Matrix Speller"}),"."]}),"\n",(0,l.jsx)(n.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,l.jsx)(n.p,{children:"Les ICM basent leur fonctionnement sur la d\xe9tection de singularit\xe9s dans l'activit\xe9 c\xe9r\xe9brale, par l'interm\xe9diaire de techniques d'enregistrement telles que l'\xe9lectroenc\xe9phalographie. Dans le cas des ICM non invasives, la principale difficult\xe9 r\xe9side dans le fait que les signaux consid\xe9r\xe9s sont faibles et soumis \xe0 une grande variabilit\xe9 inter- et intra-individus."}),"\n",(0,l.jsx)(n.p,{children:"Le choix de la singularit\xe9 \xe0 consid\xe9rer (i.e. le choix du marqueur physiologique) est d\xe9terminant : celle-ci doit \xeatre facilement rep\xe9rable et reli\xe9e \xe0 un \xe9tat mental particulier."}),"\n",(0,l.jsx)(n.p,{children:"Les caract\xe9ristiques techniques de la P300 en font une onde privil\xe9gi\xe9e pour la fabrication d'ICM comme le P300 Matrix Speller. Cependant, son apparition et ses propri\xe9t\xe9s sont corr\xe9l\xe9es \xe0 de nombreux facteurs biologiques ainsi qu'aux modalit\xe9s de l'exp\xe9rience et de la stimulation utilis\xe9e. Ce marqueur physiologique est donc sujet \xe0 une importante variabilit\xe9."}),"\n",(0,l.jsx)(n.p,{children:"Il devient alors n\xe9cessaire de trier l'information afin de diff\xe9rencier les signaux int\xe9ressants et fiables, tout en prenant en compte les particularit\xe9s de la t\xe2che et du profil de l'utilisateur. Cela implique un gros travail d'analyse des donn\xe9es ainsi que l'adaptation du syst\xe8me aux param\xe8tres de l'exp\xe9rience."}),"\n","\n",(0,l.jsxs)(n.section,{"data-footnotes":!0,className:"footnotes",children:[(0,l.jsx)(n.h2,{className:"sr-only",id:"footnote-label",children:"Footnotes"}),"\n",(0,l.jsxs)(n.ol,{children:["\n",(0,l.jsxs)(n.li,{id:"user-content-fn-clerc",children:["\n",(0,l.jsxs)(n.p,{children:["Clerc, M., Bougrain, L. et Lotte, F., ",(0,l.jsx)(n.em,{children:"Les interfaces cerveau-ordinateur 1 : fondements et m\xe9thodes"}),", ISTE \xe9ditions, 2016. ",(0,l.jsx)(n.a,{href:"#user-content-fnref-clerc","data-footnote-backref":"","aria-label":"Back to reference 1",className:"data-footnote-backref",children:"\u21a9"})]}),"\n"]}),"\n"]}),"\n"]})]})}function h(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,l.jsx)(n,{...e,children:(0,l.jsx)(m,{...e})}):m(e)}},28453(e,n,t){t.d(n,{R:()=>a,x:()=>l});var i=t(96540);const s={},r=i.createContext(s);function a(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);